'use client';
import { useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/context/AuthContext';
import { User, Activity, Search, ChevronDown, Calendar, LogOut, ShoppingCart } from 'lucide-react';
import LoginModal from './LoginModal';

export default function Navbar() {
  const { user, logout } = useAuth();
  const [showLogin, setShowLogin] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);

  return (
    <>
      <nav style={{ 
        position: 'fixed', 
        top: 0, 
        left: 0, 
        right: 0, 
        zIndex: 1000, 
        height: 'var(--header-height)',
        background: '#fff',
        borderBottom: '1px solid #e5e7eb',
        display: 'flex',
        alignItems: 'center'
      }}>
        <div className="container" style={{ 
          width: '100%',
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          gap: '2rem'
        }}>
          {/* Logo & Location */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
              <Link href="/" style={{ 
                fontSize: '1.8rem', 
                fontWeight: '800', 
                display: 'flex', 
                alignItems: 'center', 
                gap: '8px',
                color: 'var(--brand)',
                textDecoration: 'none'
              }}>
                 <span style={{ color: 'var(--brand-yellow)' }}>Su</span>vidha
              </Link>
              
              <div style={{ display: 'flex', flexDirection: 'column', fontSize: '0.85rem', lineHeight: '1.2' }}>
                  <span style={{ fontWeight: 'bold' }}>Delivery in 15 minutes</span>
                  <span style={{ color: '#666' }}>Mumbai, India</span>
              </div>
          </div>

          {/* Search Bar (Desktop) */}
          <div style={{ 
              flex: 1, 
              maxWidth: '600px', 
              background: '#f3f4f6', 
              borderRadius: '8px', 
              padding: '0.7rem 1rem', 
              display: 'flex', 
              alignItems: 'center', 
              gap: '10px' 
          }}>
              <Search size={18} color="#666" />
              <input 
                 type="text" 
                 placeholder='Search "X-ray"' 
                 style={{ 
                     background: 'transparent', 
                     border: 'none', 
                     outline: 'none', 
                     flex: 1, 
                     fontSize: '0.95rem' 
                 }}
              />
          </div>
          
          {/* Right Actions */}
          <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
              {user ? (
                <div style={{ position: 'relative' }}>
                   <button 
                      onClick={() => setShowDropdown(!showDropdown)}
                      style={{ background: 'transparent', border: 'none', cursor: 'pointer', fontSize: '1rem', fontWeight: '500' }}
                   >
                     Profile
                   </button>
                   {/* Dropdown would go here similar to before */}
                   {showDropdown && (
                     <div style={{ position: 'absolute', top: '150%', right: 0, background: '#fff', border: '1px solid #ddd', borderRadius: '8px', padding: '10px', width: '150px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}>
                         <button onClick={logout} style={{ background: 'transparent', border: 'none', color: 'red', cursor: 'pointer' }}>Logout</button>
                     </div>
                   )}
                </div>
              ) : (
                <button 
                  onClick={() => setShowLogin(true)}
                  style={{ background: 'transparent', border: 'none', fontWeight: '500', fontSize: '1.1rem', cursor: 'pointer' }}
               >
                  Login
                </button>
              )}
              
              <button className="btn btn-primary" style={{ borderRadius: '8px', display: 'flex', alignItems: 'center', gap: '8px', padding: '0.6rem 1.2rem' }}>
                  <ShoppingCart size={18} /> My Cart
              </button>
          </div>
        </div>
      </nav>
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} />
    </>
  );
}
